    if a % b == 0:
        return 0
    else:
        return b - (a % b)

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []
    for _ in range(t):
        a = int(data[index])
        index += 1
        b = int(data[index])
